def find_hollow_frames(grid, bg_val):
    h = len(grid)
    w = len(grid[0])
    frames = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg_val:
                continue

            color = grid[r][c]
            cells = []
            for rr in range(h):
                for cc in range(w):
                    if grid[rr][cc] == color:
                        cells.append((rr, cc))

            if len(cells) < 6:
                continue

            min_r = min(c[0] for c in cells)
            max_r = max(c[0] for c in cells)
            min_c = min(c[1] for c in cells)
            max_c = max(c[1] for c in cells)

            box = (min_r, min_c, max_r, max_c)

            boundary_cells = []
            interior_cells = []

            for r2 in range(min_r, max_r + 1):
                for c2 in range(min_c, max_c + 1):
                    if min_r < r2 < max_r and min_c < c2 < max_c:
                        interior_cells.append((r2, c2))
                    else:
                        boundary_cells.append((r2, c2))

            boundary_is_color = all(grid[r][c] == grid[min_r][min_c] for r, c in boundary_cells)
            interior_is_bg = all(grid[r][c] == bg_val for r, c in interior_cells)

            if boundary_is_color and interior_is_bg:
                int_h = max_r - min_r - 1
                int_w = max_c - min_c - 1

                if int_h > 0 and int_w > 0:
                    frame = {
                        'bbox': box,
                        'color': grid[min_r][min_c],
                        'interior': (int_h, int_w),
                        'interior_cells': set(interior_cells)
                    }
                    # Use bbox as key to avoid duplicates
                    if not any(f['bbox'] == box for f in frames):
                        frames.append(frame)

    return frames

def transform(grid):
    bg = 9
    new_grid = [row[:] for row in grid]
    frames = find_hollow_frames(grid, bg)

    for frame in frames:
        int_h, int_w = frame['interior']

        # Determine fill color
        if int_h == int_w:  # Square interior
            fill = 7 if int_h % 2 == 1 else 2
        else:  # Non-square
            fill = 2

        for rr, cc in frame['interior_cells']:
            new_grid[rr][cc] = fill

    return new_grid

